import { expect, test } from 'vitest';
import { splitName } from './name';

test('가운데 이름이 있어도 성을 제대로 뗀다', () => {
  expect(splitName('김 하늘 별')).toEqual({ last: '김', first: '하늘 별' });
});

import { expect, test } from '@playwright/test';

test('할 일을 추가하면 목록에 보인다', async ({ page }) => {
  await page.goto('/');
  await page.getByLabel('할 일').fill('빨래');
  await page.getByRole('button', { name: '추가' }).click();
  await expect(page.getByRole('listitem')).toHaveText(['빨래']);
});
